  assertThat(jdbc.queryForObject("select status from fs_recognition where id=?",String.class,id)).isEqualTo("ESTIMATED");UUID invoice=invoice("120.00");as(owner,"finance.submit");call(()->service.match(new Match(UUID.randomUUID(),receipt,1,false,List.of(invoice),List.of(new InvoiceLine(line,new BigDecimal("10"),new BigDecimal("12"))),DAY,"真实发票涨价，独立确认")));as(finance,"finance.review");call(()->service.confirm(id,new Confirm(UUID.randomUUID(),2,"已独立核实20元差异")));
