 @Test void consumedOriginalBatchCannotBeReturnedEvenAfterReplacementStockArrives(){UUID rec=confirmed();jdbc.update("insert into store_inventory_movement(id,tenant_id,hotel_org_unit_id,item_id,movement_type,quantity_delta,quantity_before,quantity_after,unit_cost_snapshot,value_delta,reason,source_type,idempotency_key,request_hash,actor_account_id) values(?,?,?,?,'CONSUMPTION',-8,10,2,10,-80,'已领用','MANUAL',?,?,?)",UUID.randomUUID(),T,hotel,item,UUID.randomUUID().toString(),"b".repeat(64),owner);jdbc.update("update store_inventory_balance set quantity=2,inventory_value=20 where item_id=?",item);as(owner,"finance.submit");UUID ret=UUID.randomUUID();call(()->service.createReturn(new Return(ret,rec,line,new BigDecimal("3"),"RETURN",DAY,"不能退已经使用的数量")));as(reviewer,"finance.review");assertThatThrownBy(()->call(()->service.reviewReturn(ret,new ReturnReview(UUID.randomUUID(),0,true,"核验")))).hasMessageContaining("已领用");assertThat(jdbc.queryForObject("select status from fs_return where id=?",String.class,ret)).isEqualTo("PENDING");}
 @Test void concurrentSameReceiptOnlyOneFinancialRecognition(){var pool=Executors.newFixedThreadPool(2);try{var in=new Match(UUID.randomUUID(),receipt,0,true,List.of(),List.of(),DAY,"并发暂估");var tasks=List.of(pool.submit(()->{as(owner,"*");return call(()->service.match(in));}),pool.submit(()->{as(owner,"*");return call(()->service.match(in));}));for(var future:tasks)assertThatCode(()->future.get(20,TimeUnit.SECONDS)).doesNotThrowAnyException();assertThat(jdbc.queryForObject("select count(*) from fs_recognition where receipt_id=?",Integer.class,receipt)).isOne();}finally{pool.shutdownNow();}}
